package com.huy.enterprise.company;
import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequiredArgsConstructor public class CompanyController {private final CompanyService service;@GetMapping("/api/companies") List<CompanyResponse> companies(){return service.companies();}@PostMapping("/api/companies") @ResponseStatus(HttpStatus.CREATED) CompanyResponse company(@Valid @RequestBody CompanyRequest r){return service.company(null,r);}@PutMapping("/api/companies/{id}") CompanyResponse company(@PathVariable UUID id,@Valid @RequestBody CompanyRequest r){return service.company(id,r);}@GetMapping("/api/departments") List<DepartmentResponse> departments(){return service.departments();}@PostMapping("/api/departments") @ResponseStatus(HttpStatus.CREATED) DepartmentResponse department(@Valid @RequestBody DepartmentRequest r){return service.department(null,r);}@PutMapping("/api/departments/{id}") DepartmentResponse department(@PathVariable UUID id,@Valid @RequestBody DepartmentRequest r){return service.department(id,r);}@GetMapping("/api/employees") List<EmployeeResponse> employees(){return service.employees();}@PostMapping("/api/employees") @ResponseStatus(HttpStatus.CREATED) EmployeeResponse employee(@Valid @RequestBody EmployeeRequest r){return service.employee(null,r);}@PutMapping("/api/employees/{id}") EmployeeResponse employee(@PathVariable UUID id,@Valid @RequestBody EmployeeRequest r){return service.employee(id,r);}}
